def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Recolor the maximal uniform rectangles with height >= 4 and width >= 5.
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            maxw = w - c0
            for r1 in range(r0, h):
                run = 0
                while c0 + run < w and grid[r1][c0 + run] == color:
                    run += 1
                maxw = min(maxw, run)
                if r1 - r0 + 1 >= 4 and maxw >= 5:
                    for r in range(r0, r1 + 1):
                        for c in range(c0, c0 + maxw):
                            out[r][c] = 4
    return out
